package com.fittrack.coach;
import com.fittrack.ai.AiProvider;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/coach") public class CoachController {private final JdbcTemplate j;private final AiProvider ai;public CoachController(JdbcTemplate j,AiProvider a){this.j=j;this.ai=a;}@PostMapping("/analyze")public Map<String,Object> analyze(@AuthenticationPrincipal String u){var facts=new LinkedHashMap<String,Object>();facts.put("dailyMetrics",j.queryForList("SELECT metric_date,steps,sleep_hours,calories_burned,active_minutes FROM daily_metrics WHERE user_id=? ORDER BY metric_date DESC LIMIT 14",u));facts.put("bodyMetrics",j.queryForList("SELECT metric_date,weight_lb,body_fat_pct FROM body_metrics WHERE user_id=? ORDER BY metric_date DESC LIMIT 14",u));facts.put("workouts",j.queryForList("SELECT workout_date,duration_minutes,calories_burned,completed FROM workouts WHERE user_id=? ORDER BY workout_date DESC LIMIT 20",u));facts.put("meals",j.queryForList("SELECT meal_date,calories,protein_g FROM meals WHERE user_id=? ORDER BY meal_date DESC LIMIT 20",u));return Map.of("analysis",ai.analyzeCoach(facts.toString()),"facts",facts);}@PostMapping("/weekly-review")public Map<String,String>weekly(@AuthenticationPrincipal String u){return Map.of("review",ai.analyzeCoach("weekly factual summary for user "+u));}}

